import sys, json, hashlib, base64, re, difflib, datetime, secrets, mimetypes

# THE ONE PLACE CONTENT IS MADE (file-space, GH #900). Every byte of a file in
# this space enters here: a new file (`create`), an edit of the main line (every
# write op of `in_write`, with the caller's `base` as the compare-and-swap
# token), an edit of a workspace's working version (the same ops with `hop.ws`),
# and the three content requests of `./ws` on `in_put` (`merge3`, `patch`,
# `create`). Content is kept as content-addressed blocks (sha256) under an
# immutable version; the main line of a file is a pointer (`files.head`) that
# only moves by `update ... where head=<read> and lock=''` -- a compare-and-swap
# judged by `rows_affected`, never by a select before it.
#
# Order of the store writes, and why (a store bundle is not a transaction,
# `store/cell.rs:46-56`): blocks -> version -> pointer swing -> `line` row. An
# abort after any step leaves the store readable: blocks and versions no pointer
# names are invisible, and a `line` row is only ever written for a swing that
# happened. Every phase parks its working values in `pending` (dev-rules § 8c)
# and reads them back in the same bundle; the context carries only the pending
# key (`cur_call`), the phase and the origin -- never a value.
doc = json.load(sys.stdin)
d = doc.get("body") or {}
envelope = doc.get("envelope") or {}
P = doc.get("params") or {}
header = envelope.get("header") or {}
hop = header.get("hop") or {}
ctx = header.get("context") or {}

ME = "write"
FMT = "%Y-%m-%dT%H:%M:%S.%fZ"

# -- blocks (README § 2.4) ------------------------------------------------------
BLOCK_MOD = 32
BLOCK_MAX_LINES = 256
BLOCK_MAX_BYTES = 16384
BIN_BLOCK = 196608
TRANCHE = 200
REGEX_MAX = 500
PATCH_SLACK = 50
MARKS = ("<<<<<<< ours", "||||||| base", "=======", ">>>>>>> theirs")
PUNCT = {
    "‘": "'", "’": "'", "‚": "'", "‛": "'", "′": "'",
    "“": '"', "”": '"', "„": '"', "‟": '"', "″": '"',
    "«": '"', "»": '"',
    "‐": "-", "‑": "-", "‒": "-", "–": "-", "—": "-",
    "―": "-", "−": "-",
    " ": " ", " ": " ", " ": " ", " ": " ", " ": " ",
    "…": "...",
}
WRITE_OPS = ("create", "replace", "replace_regex", "replace_lines", "insert", "delete",
             "overwrite", "patch", "snapshot", "revert", "remove")
PUT_OPS = ("merge3", "patch", "create")


def is_text(data):
    """UTF-8 without NUL is text (README § 2.4); everything else is binary."""
    if b"\x00" in data:
        return False
    try:
        data.decode("utf-8")
        return True
    except UnicodeDecodeError:
        return False


def _boundary(line):
    h = hashlib.sha256(line).digest()
    return ((h[0] << 8) | h[1]) % BLOCK_MOD == 0


def chunk(data, is_text):
    """The blocks of `data`, in order (README § 2.4). Text: a block ends after a
    line (its bytes with the line end) whose sha256 starts with two bytes that
    are 0 mod 32, and at the latest after 256 lines or once it holds 16 KiB --
    cuts fall only at line ends, so a block is valid UTF-8. One edited line
    touches at most two blocks where only hash boundaries cut (lines under
    64 B: the 16 KiB cap cannot come before the 256-line cap); a capped cut
    counts from the block's start, so behind an edit the chain resynchronises
    at the next hash boundary instead (OR-FH-84, measured up to 10 new blocks
    for 1.2-1.6 KB lines). Binary: fixed 192 KiB. An empty file has NO block
    (the one form chosen and locked, GH #900 task 1)."""
    if not data:
        return []
    if not is_text:
        return [data[i:i + BIN_BLOCK] for i in range(0, len(data), BIN_BLOCK)]
    out, start, lines, pos, n = [], 0, 0, 0, len(data)
    while pos < n:
        nl = data.find(b"\n", pos)
        end = n if nl < 0 else nl + 1
        lines += 1
        if _boundary(data[pos:end]) or lines >= BLOCK_MAX_LINES \
                or end - start >= BLOCK_MAX_BYTES or end == n:
            out.append(data[start:end])
            start, lines = end, 0
        pos = end
    return out


def version_of(data):
    return hashlib.sha256(data).hexdigest()


def block_hash(block):
    return hashlib.sha256(block).hexdigest()


ID_RE = re.compile(r"^fh-[0-9a-f]{12}$")
HEX_RE = re.compile(r"^[0-9a-f]{4,64}$")
NAME_RE = re.compile(r"^[A-Za-z0-9._-]{1,64}$")


# -- twins of `read` (README § 2.1/2.5; GH #899 locks them word for word) -------
def parse_addr(s):
    """An address -> {file, path, at, ref, anchor}; `at` is `head`, `v`
    (`ref` a hex prefix), `ws` or `snap` (`ref` a name). A malformed address
    is {error: 'bad_address'}. An anchor (`#...`) is parsed, never resolved."""
    if not isinstance(s, str) or not s.strip() or len(s) > 1024:
        return {"error": "bad_address"}
    s = s.strip()
    anchor = ""
    if "#" in s:
        s, anchor = s.split("#", 1)
        if not anchor:
            return {"error": "bad_address"}
    at, ref = "head", ""
    if "@" in s:
        base, suffix = s.rsplit("@", 1)
        if suffix.startswith("ws:") or suffix.startswith("snap:"):
            kind, name = suffix.split(":", 1)
            if not NAME_RE.match(name):
                return {"error": "bad_address"}
            at, ref, s = kind, name, base
        elif HEX_RE.match(suffix):
            at, ref, s = "v", suffix, base
        elif ID_RE.match(base):
            return {"error": "bad_address"}
    if ID_RE.match(s):
        return {"file": s, "path": "", "at": at, "ref": ref, "anchor": anchor}
    if s.startswith("/") and "\x00" not in s and "//" not in s and len(s) > 1 \
            and not s.endswith("/"):
        return {"file": "", "path": s, "at": at, "ref": ref, "anchor": anchor}
    return {"error": "bad_address"}


def line_hash(line):
    """`h4`: the first four hex digits of the sha256 of one line without its
    line ending (`\\n`, `\\r\\n`)."""
    if line.endswith("\n"):
        line = line[:-1]
    if line.endswith("\r"):
        line = line[:-1]
    return hashlib.sha256(line.encode("utf-8")).hexdigest()[:4]


# -- lines --------------------------------------------------------------------
def eol_of(text):
    """`\\r\\n` when every line end of the file is one, else `\\n`."""
    n = text.count("\n")
    return "\r\n" if n and text.count("\r\n") == n else "\n"


def to_lf(text, eol):
    return text.replace("\r\n", "\n") if eol == "\r\n" else text


def from_lf(text, eol):
    return text.replace("\n", "\r\n") if eol == "\r\n" else text


def split_lines(text):
    """(lines without their ends, whether the last line ended) of LF text."""
    if text == "":
        return [], False
    parts = text.split("\n")
    if parts[-1] == "":
        return parts[:-1], True
    return parts, False


def join_lines(lines, final_nl):
    if not lines:
        return ""
    return "\n".join(lines) + ("\n" if final_nl else "")


def count_lines(text):
    return len(split_lines(text)[0])


def view(lines, first, last):
    """Lines `first..last` (1-based, clipped) in the read form `n:h4|text`."""
    first, last = max(1, first), min(len(lines), last)
    return ["%d:%s|%s" % (i, line_hash(lines[i - 1]), lines[i - 1])
            for i in range(first, last + 1)]


def path_norm(path):
    """`/`-prefixed, no `..`, no empty or `.` segment -> the path, else ''."""
    p = str(path or "")
    segs = p.split("/")
    if not p.startswith("/") or len(segs) < 2:
        return ""
    segs = segs[1:]
    if any(s in ("", ".", "..") for s in segs):
        return ""
    return "/" + "/".join(segs)


def oneline_of(text):
    for ln in split_lines(text)[0]:
        if ln.strip():
            return ln.strip()[:120]
    return ""


# -- the replace cascade (S-27-1) ---------------------------------------------
def _norm_map(text, stage):
    """`text` normalised for stage 2..4, with the index in `text` of every
    character kept. 2: trailing whitespace of every line dropped; 3: plus
    leading whitespace; 4: plus typographic punctuation folded. Line ends are
    already LF (the cell works on LF text)."""
    out, pos = [], []
    for start, line in _lines_at(text):
        body = line[:-1] if line.endswith("\n") else line
        nl = line.endswith("\n")
        lo, hi = 0, len(body)
        while hi > lo and body[hi - 1] in " \t":
            hi -= 1
        if stage >= 3:
            while lo < hi and body[lo] in " \t ":
                lo += 1
        for i in range(lo, hi):
            ch = body[i]
            rep = PUNCT.get(ch, ch) if stage >= 4 else ch
            for r in rep:
                out.append(r)
                pos.append(start + i)
        if nl:
            out.append("\n")
            pos.append(start + len(body))
    return "".join(out), pos


def _lines_at(text):
    i, n = 0, len(text)
    while i < n:
        j = text.find("\n", i)
        j = n if j < 0 else j + 1
        yield i, text[i:j]
        i = j


def _find_all(hay, needle):
    out, i = [], 0
    while True:
        k = hay.find(needle, i)
        if k < 0:
            return out
        out.append((k, k + len(needle)))
        i = k + len(needle)


def _indent(s):
    return s[:len(s) - len(s.lstrip(" \t"))]


def cascade_find(text, old, expected=1):
    """Where `old` stands in `text` (both LF): the first stage with a hit wins
    (1 exact, 2 trailing whitespace, 3 indentation, 4 punctuation), and the
    count is judged on THAT stage -- `expected` 1 (default) = exactly one,
    `all` = at least one, n = exactly n. -> {stage, count, spans:[{from, to,
    indent}]} or {error: not_found|ambiguous, count, lines}. `indent` is the
    indentation of the matched first line when the hit starts at a line start
    on stage 3/4, else None."""
    if old == "":
        return {"error": "bad_request", "count": 0, "lines": []}
    exp = expected if expected not in (None, "") else 1
    for stage in (1, 2, 3, 4):
        if stage == 1:
            spans = [{"from": s, "to": e, "indent": None} for s, e in _find_all(text, old)]
        else:
            ht, hp = _norm_map(text, stage)
            nt, _ = _norm_map(old, stage)
            nt = nt.rstrip("\n") if not old.endswith("\n") else nt
            if nt.strip() == "":
                continue
            spans = []
            for s, e in _find_all(ht, nt):
                a, b = hp[s], hp[e - 1] + 1
                ind = None
                if stage >= 3 and (s == 0 or ht[s - 1] == "\n"):
                    ls = text.rfind("\n", 0, a) + 1
                    ind = text[ls:a]
                    a = ls
                spans.append({"from": a, "to": b, "indent": ind})
        if not spans:
            continue
        lines = [text.count("\n", 0, sp["from"]) + 1 for sp in spans]
        n = len(spans)
        ok = (exp == "all") or (str(exp).isdigit() and n == int(exp))
        if not ok:
            return {"error": "ambiguous", "stage": stage, "count": n, "lines": lines}
        return {"stage": stage, "count": n, "spans": spans, "lines": lines}
    return {"error": "not_found", "count": 0, "lines": []}


def shift_indent(new, old, indent):
    """`new` moved by the indentation difference of `old`'s first line and the
    matched line (`indent`): every line that starts with old's indentation gets
    the matched one instead; a line indented less loses as much of it."""
    if indent is None:
        return new
    first = old.lstrip("\n").split("\n")[0]
    oi = _indent(first)
    out = []
    for k, ln in enumerate(new.split("\n")):
        if ln.strip() == "":
            out.append(ln)
            continue
        if ln.startswith(oi):
            out.append(indent + ln[len(oi):])
        else:
            lead = _indent(ln)
            cut = len(oi) - len(lead)
            keep = indent[:len(indent) - cut] if cut < len(indent) else ""
            out.append(keep + ln[len(lead):])
    return "\n".join(out)


def apply_cascade(text, found, old, new):
    """`text` with every span of `found` replaced by `new` (indentation-shifted
    on stage 3/4). Normalisation was for the comparison only: what is written
    is `new` as given."""
    out, last = [], 0
    for sp in found["spans"]:
        out.append(text[last:sp["from"]])
        out.append(shift_indent(new, old, sp["indent"]) if found["stage"] >= 3 else new)
        last = sp["to"]
    out.append(text[last:])
    return "".join(out)


# -- line ops -----------------------------------------------------------------
def _new_lines(text):
    t = str(text or "")
    if t.endswith("\n"):
        t = t[:-1]
    return [] if t == "" and not str(text or "").endswith("\n") else t.split("\n")


def apply_replace_lines(text, frm, to, hashes, new):
    """Lines `frm..to` (1-based, inclusive) replaced by `new`, if every `h4` in
    `hashes` still names its line; else {error: stale_lines, lines}."""
    lines, fin = split_lines(text)
    try:
        frm, to = int(frm), int(to)
    except Exception:
        return {"error": "bad_request"}
    if frm < 1 or to < frm or to > len(lines):
        return {"error": "out_of_range", "lines": len(lines)}
    hs = [str(h) for h in (hashes or [])]
    cur = [line_hash(lines[i - 1]) for i in range(frm, to + 1)]
    if hs != cur:
        return {"error": "stale_lines", "lines": view(lines, frm, to)}
    lines[frm - 1:to] = _new_lines(new)
    return {"text": join_lines(lines, fin or not lines)}


def apply_insert(text, line, where, new):
    """`new` before or after line `line` of the base (after 0 = at the top,
    before n+1 = at the end)."""
    lines, fin = split_lines(text)
    try:
        line = int(line)
    except Exception:
        return {"error": "bad_request"}
    at = line - 1 if where == "before" else line
    if where not in ("before", "after") or at < 0 or at > len(lines):
        return {"error": "out_of_range", "lines": len(lines)}
    add = _new_lines(new)
    if not add:
        return {"error": "bad_request"}
    lines[at:at] = add
    return {"text": join_lines(lines, fin or not text)}


def apply_delete(text, frm, to):
    lines, fin = split_lines(text)
    try:
        frm, to = int(frm), int(to)
    except Exception:
        return {"error": "bad_request"}
    if frm < 1 or to < frm or to > len(lines):
        return {"error": "out_of_range", "lines": len(lines)}
    del lines[frm - 1:to]
    return {"text": join_lines(lines, fin)}


# -- patch --------------------------------------------------------------------
HUNK = re.compile(r"^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@")


def parse_hunks(diff):
    """The hunks of a unified diff of ONE file: [(old_start, old, new, tags)],
    old/new the line lists (context + removed / context + added), tags the
    hunk's lines in order (' ', '-', '+'). Header lines optional;
    `\\ No newline at end of file` ignored.

    A hunk's body is read by the counts of its head (`-a,b +c,d`): while lines
    are owed, `--- x` is the removed line `-- x` and `+++ x` the added `++ x`
    (a SQL/Lua comment), and an empty line is an empty context line. Only
    once the counts are met does `--- `/`+++ ` read as a file header again --
    guessing by prefix alone dropped such lines silently (review W I-2). A body
    longer than its counts (a hand-written diff) still extends the hunk by
    prefix."""
    hunks, cur, owe_old, owe_new = [], None, 0, 0
    text = str(diff or "")
    if text.endswith("\n"):
        text = text[:-1]
    for ln in text.split("\n"):
        m = HUNK.match(ln)
        if m:
            cur = (int(m.group(1)), [], [], [])
            hunks.append(cur)
            owe_old = int(m.group(2)) if m.group(2) is not None else 1
            owe_new = int(m.group(4)) if m.group(4) is not None else 1
            continue
        if cur is None:
            continue
        if owe_old > 0 or owe_new > 0:
            tag = ln[:1] if ln else " "
            if tag == "\\":
                continue
            if tag == " " and owe_old > 0 and owe_new > 0:
                cur[1].append(ln[1:])
                cur[2].append(ln[1:])
                cur[3].append(" ")
                owe_old, owe_new = owe_old - 1, owe_new - 1
                continue
            if tag == "-" and owe_old > 0:
                cur[1].append(ln[1:])
                cur[3].append("-")
                owe_old -= 1
                continue
            if tag == "+" and owe_new > 0:
                cur[2].append(ln[1:])
                cur[3].append("+")
                owe_new -= 1
                continue
            owe_old = owe_new = 0
        if ln.startswith(" "):
            cur[1].append(ln[1:])
            cur[2].append(ln[1:])
            cur[3].append(" ")
        elif ln.startswith("-") and not ln.startswith("--- "):
            cur[1].append(ln[1:])
            cur[3].append("-")
        elif ln.startswith("+") and not ln.startswith("+++ "):
            cur[2].append(ln[1:])
            cur[3].append("+")
        elif ln == "":
            continue
        elif ln.startswith("\\"):
            continue
        else:
            cur = None
    return hunks


def _same(a, b, loose):
    if not loose:
        return a == b
    return len(a) == len(b) and all(x.rstrip() == y.rstrip() for x, y in zip(a, b))


def apply_patch(text, diff):
    """`text` with the hunks of `diff` applied in order: context must match
    exactly (or with trailing whitespace ignored, cascade stage 2) at the stated
    line or, if found exactly once, up to 50 lines off. All or nothing ->
    {text} or {error: patch_failed, hunk (1-based), message}."""
    hunks = parse_hunks(diff)
    if not hunks:
        return {"error": "patch_failed", "hunk": 0, "message": "no hunk in the diff"}
    lines, fin = split_lines(text)
    out, pos, delta = [], 0, 0
    for k, (start, old, new, tags) in enumerate(hunks, 1):
        want = (start - 1 if old else start) + delta
        where = None
        for loose in (False, True):
            if want >= pos and want + len(old) <= len(lines) \
                    and _same(lines[want:want + len(old)], old, loose):
                where = want
                break
            hits = [i for i in range(max(pos, want - PATCH_SLACK),
                                     min(len(lines) - len(old), want + PATCH_SLACK) + 1)
                    if _same(lines[i:i + len(old)], old, loose)]
            if len(hits) == 1:
                where = hits[0]
                break
            if len(hits) > 1:
                return {"error": "patch_failed", "hunk": k,
                        "message": "context matches %d places" % len(hits)}
        if where is None:
            return {"error": "patch_failed", "hunk": k,
                    "message": "context not found near line %d" % start}
        out.extend(lines[pos:where])
        i, j = where, 0
        for t in tags:
            # a context line is the file's own (a loose match keeps its
            # trailing whitespace), a removed one is skipped, an added one taken
            if t == " ":
                out.append(lines[i])
                i, j = i + 1, j + 1
            elif t == "-":
                i += 1
            else:
                out.append(new[j])
                j += 1
        pos = where + len(old)
        delta = where - (start - 1 if old else start)
    out.extend(lines[pos:])
    return {"text": join_lines(out, fin or (bool(out) and not lines))}


# -- merge3 and unified -------------------------------------------------------
def _sync_regions(base, a, b):
    am = difflib.SequenceMatcher(None, base, a, autojunk=False).get_matching_blocks()
    bm = difflib.SequenceMatcher(None, base, b, autojunk=False).get_matching_blocks()
    ia = ib = 0
    out = []
    while ia < len(am) and ib < len(bm):
        abase, amatch, alen = am[ia]
        bbase, bmatch, blen = bm[ib]
        lo, hi = max(abase, bbase), min(abase + alen, bbase + blen)
        if lo < hi:
            out.append((lo, hi, amatch + lo - abase, amatch + hi - abase,
                        bmatch + lo - bbase, bmatch + hi - bbase))
        if abase + alen < bbase + blen:
            ia += 1
        else:
            ib += 1
    out.append((len(base), len(base), len(a), len(a), len(b), len(b)))
    return out


def merge3(base, ours, theirs):
    """Line-wise three-way merge of LF texts: hunks that do not overlap are
    taken, the same change once, an overlap (adjacency included) is a conflict
    written with the four marks. -> {text, clean, conflicts:[{from, to,
    theirs_from, theirs_to}]}, `from`/`to` the lines of the marked region in
    the result, `theirs_*` the region in `theirs` (1-based, may be empty:
    to = from - 1)."""
    bl = base.splitlines(True)
    al = ours.splitlines(True)
    tl = theirs.splitlines(True)
    out, conflicts = [], []
    iz = ia = ib = 0

    def nl(chunk):
        return [x if x.endswith("\n") else x + "\n" for x in chunk]

    for zm, ze, am, ae, bm, be in _sync_regions(bl, al, tl):
        ca, cb, cz = al[ia:am], tl[ib:bm], bl[iz:zm]
        if ca or cb or cz:
            if ca == cb:
                out.extend(ca)
            elif ca == cz:
                out.extend(cb)
            elif cb == cz:
                out.extend(ca)
            else:
                first = len(out) + 1
                out.append(MARKS[0] + "\n")
                out.extend(nl(ca))
                out.append(MARKS[1] + "\n")
                out.extend(nl(cz))
                out.append(MARKS[2] + "\n")
                out.extend(nl(cb))
                out.append(MARKS[3] + "\n")
                conflicts.append({"from": first, "to": len(out),
                                  "theirs_from": ib + 1, "theirs_to": bm})
        out.extend(al[am:ae])
        iz, ia, ib = ze, ae, be
    return {"text": "".join(out), "clean": not conflicts, "conflicts": conflicts}


def has_marks(text):
    """Whether a conflict is still marked: the two named marks only -- a line
    `=======` alone is a Markdown heading underline as often as a mark
    (review W m-3)."""
    return any(ln.startswith(MARKS[0]) or ln.startswith(MARKS[3])
               for ln in split_lines(text)[0])


def unified(a, b, ctx=3):
    """The unified diff of LF texts `a` -> `b` (lines without ends)."""
    return "\n".join(difflib.unified_diff(split_lines(a)[0], split_lines(b)[0],
                                          "base", "new", n=ctx, lineterm=""))


def changed_share(a, b):
    """The share of lines a change touches (for the `use_replace` hint)."""
    al, bl = split_lines(a)[0], split_lines(b)[0]
    sm = difflib.SequenceMatcher(None, al, bl, autojunk=False)
    same = sum(n for _, _, n in sm.get_matching_blocks())
    return (max(len(al), len(bl)) - same) / float(max(len(al), len(bl), 1))


def compute(op, args, text):
    """The pure core of one text op against the base content (LF). -> {text,
    stage?} or {error, ...}."""
    if op == "replace":
        old, new = args.get("old"), args.get("new")
        if not isinstance(old, str) or not isinstance(new, str):
            return {"error": "bad_request", "message": "replace needs old and new"}
        f = cascade_find(text, to_lf(old, "\r\n"), args.get("expected", 1))
        if "error" in f:
            return {"error": f["error"], "count": f["count"], "lines": f["lines"],
                    "message": "old %s (%d hits)" % (f["error"].replace("_", " "), f["count"])}
        return {"text": apply_cascade(text, f, to_lf(old, "\r\n"), to_lf(new, "\r\n")),
                "stage": f["stage"]}
    if op == "replace_regex":
        pat, repl = args.get("pattern"), args.get("repl")
        if not isinstance(pat, str) or not isinstance(repl, str) or len(pat) > REGEX_MAX:
            return {"error": "bad_request", "message": "pattern (<= 500 chars) and repl"}
        try:
            rx = re.compile(pat, re.MULTILINE)
        except re.error as e:
            return {"error": "bad_request", "message": "pattern: %s" % e}
        n = sum(1 for _ in rx.finditer(text))
        exp = args.get("expected", 1)
        if not ((exp == "all" and n >= 1) or (str(exp).isdigit() and n == int(exp))):
            return {"error": "count_mismatch", "count": n,
                    "message": "pattern matched %d times" % n}
        try:
            return {"text": rx.sub(repl, text)}
        except re.error as e:
            return {"error": "bad_request", "message": "repl: %s" % e}
    if op == "replace_lines":
        return apply_replace_lines(text, args.get("from"), args.get("to"),
                                   args.get("hashes"), to_lf(str(args.get("new") or ""), "\r\n"))
    if op == "insert":
        where = "before" if "before" in args else "after"
        line = args.get("line", args.get(where))
        return apply_insert(text, line, args.get("where", where),
                            to_lf(str(args.get("text") or ""), "\r\n"))
    if op == "delete":
        return apply_delete(text, args.get("from"), args.get("to"))
    if op == "patch":
        return apply_patch(text, args.get("diff"))
    return {"error": "unknown_op"}


# ======================================================================= I/O
def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime(FMT)


def now_us():
    return int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000000)


def emit(msgs):
    sys.stdout.write(json.dumps(msgs))
    sys.exit(0)


def note(reason):
    sys.stderr.write("file-space/write: %s\n" % reason)


def sel(table, columns, where, order=None, limit=1):
    a = {"operation": "select", "table": table, "columns": columns, "where": where,
         "limit": limit}
    if order:
        a["order_by"] = [{"col": c, "dir": o} for c, o in order]
    return a


def ins(table, row):
    return {"operation": "insert", "table": table, "row": row}


def upd(table, setv, where):
    return {"operation": "update", "table": table, "set": setv, "where": where}


def dele(table, where):
    return {"operation": "delete", "table": table, "where": where}


def legs(body):
    """The answer of a store message by tool_call id: payload, error, rows."""
    out = {}
    for m in body.get("messages") or []:
        if not isinstance(m, dict):
            continue
        try:
            payload = json.loads(m.get("text") or "null")
        except Exception:
            payload = None
        out[str(m.get("id") or "")] = {"payload": payload, "error_code": "",
                                       "rows_affected": 0}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if isinstance(r, dict):
                leg = out.setdefault(str(r.get("tool_call_id") or ""),
                                     {"payload": None, "error_code": "", "rows_affected": 0})
                leg["error_code"] = str(r.get("error_code") or "")
                leg["rows_affected"] = int(r.get("rows_affected") or 0)
    elif len(out) == 1:
        leg = next(iter(out.values()))
        leg["error_code"] = str(hop.get("error_code") or "")
        leg["rows_affected"] = int(hop.get("rows_affected") or 0)
    return out


def rows(lg, cid):
    p = (lg.get(cid) or {}).get("payload")
    return p if isinstance(p, list) else []


def one(lg, cid):
    r = rows(lg, cid)
    return r[0] if r else None


def v12(v):
    return str(v or "")[:12]


def as_list(v):
    if isinstance(v, str):
        try:
            v = json.loads(v)
        except Exception:
            return []
    return v if isinstance(v, list) else []


# -- the parked request -------------------------------------------------------
def key(st):
    return {"op_id": st["pid"], "cell": ME}


def store_msg(st, phase, ops, first=False):
    """One bundle to `./store`: park the state, then `ops`, then read the state
    back -- the next phase gets its working values from the answer, never from
    the context."""
    st["phase"] = phase
    body = json.dumps(st)
    park = ins("pending", {"op_id": st["pid"], "cell": ME, "phase": phase, "body": body,
                           "at": now()}) if first else \
        upd("pending", {"phase": phase, "body": body}, key(st))
    calls = [("park", park)] + list(ops) + [("state", sel("pending", ["cell", "body"], key(st)))]
    return {"header": {"route": "write_store", "phase": phase, "reply_cell": ME,
                       "cur_call": st["pid"]},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(args)} for cid, args in calls]}


def reply(st, body):
    """The one answer of a request: route `answer` (in_write) or `put`
    (in_put), `op`/`op_id`/`caller` mirrored."""
    route = "put" if st.get("lane") == "in_put" else "answer"
    h = {"route": route, "op": st.get("op", ""), "op_id": st.get("op_id", ""),
         "caller": st.get("caller", "")}
    if st.get("ws"):
        h["ws"] = st["ws"]
    b = {"ok": True, "op": st.get("op", ""), "op_id": st.get("op_id", "")}
    b.update(body)
    b["header"] = h
    return b


def fail(st, code, message="", **extra):
    err = {"code": code, "message": message or code.replace("_", " ")}
    err.update(extra)
    return reply(st, {"ok": False, "error": err})


def finish(st, msgs):
    """Answer and forget the parked request."""
    out = list(msgs)
    if st.get("parked"):
        out.append(store_done(st))
    emit(out)


def store_done(st):
    return {"header": {"route": "write_store", "phase": "done", "reply_cell": ME,
                       "cur_call": st["pid"]},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": "drop",
                          "text": json.dumps(dele("pending", {"op_id": st["pid"]}))}]}


def knob(name, default):
    try:
        return type(default)(P.get(name, default))
    except Exception:
        return default


def later(a, b):
    """Whether stamp `a` lies after stamp `b` (both UTC, ISO-ish)."""
    def parse(s):
        s = str(s or "").strip().replace("Z", "+00:00")
        try:
            t = datetime.datetime.fromisoformat(s)
        except Exception:
            return None
        return t if t.tzinfo else t.replace(tzinfo=datetime.timezone.utc)
    ta, tb = parse(a), parse(b)
    # an unreadable deadline counts as passed (OR-FH-77): a prepare nobody can
    # date must not hold its files forever
    return ta is not None and (tb is None or ta > tb)


def data_of(args):
    """The bytes a `create`/`overwrite` carries: `b64` wins over `text`."""
    if isinstance(args.get("b64"), str):
        try:
            return base64.b64decode(args["b64"], validate=True)
        except Exception:
            return None
    if isinstance(args.get("text"), str):
        return args["text"].encode("utf-8")
    return None


def content_of(vrow, blocks):
    """The bytes of a version from its block list and the fetched blocks."""
    out = []
    for h in as_list(vrow.get("blocks")):
        b = blocks.get(h)
        if b is None:
            return None
        out.append(b)
    return b"".join(out)


def block_rows(lg):
    have = {}
    for cid in lg:
        if cid.startswith("blk"):
            for r in rows(lg, cid):
                body = str(r.get("body") or "")
                have[str(r.get("hash"))] = base64.b64decode(body) if r.get("enc") == "b64" \
                    else body.encode("utf-8")
    return have


def tranches(hashes):
    hs = sorted(set(hashes))
    return [hs[i:i + TRANCHE] for i in range(0, len(hs), TRANCHE)]


def candidates(lg, cid, prefix):
    return [r for r in rows(lg, cid) if str(r.get("version") or "").startswith(prefix)]


def vsel(file, prefix):
    """Version rows whose id starts with `prefix`: the store has no LIKE, so the
    range start `gte prefix` in order, two rows -- a second hit with the same
    prefix is the ambiguity."""
    return sel("versions", ["version", "blocks", "bytes", "lines", "force"],
               {"file": file, "version": {"gte": prefix}}, [("version", "asc")], 2)


def resolve(st, lg, cid, prefix, known=()):
    """A version prefix -> the full id, or an error answer emitted."""
    # a known id wins only for a full token (>= 12 hex): a shorter prefix may
    # name another version too, so it goes through the ambiguity check (m-4)
    for v in known:
        if v and len(prefix) >= 12 and v.startswith(prefix):
            return v
    c = candidates(lg, cid, prefix)
    if not c:
        finish(st, [fail(st, "version_unknown", "no version %s" % prefix)])
    if len(c) > 1:
        finish(st, [fail(st, "version_ambiguous", "prefix %s names several versions" % prefix,
                         candidates=[v12(r["version"]) for r in c])])
    st.setdefault("vrows", {})[c[0]["version"]] = c[0]
    return c[0]["version"]


# ======================================================================= LANES
lane = str(hop.get("route") or "")
phase = str(ctx.get("cur_phase") or "")


def fresh_state(lane):
    args = d.get("args") if isinstance(d.get("args"), dict) else {}
    args = dict(args)
    if lane == "in_put":
        for k, v in d.items():
            if k not in ("args", "op", "file", "messages") and k not in args:
                args[k] = v
    op = str(hop.get("op") or d.get("op") or "")
    st = {"pid": "w-" + secrets.token_hex(8), "lane": lane, "op": op,
          "op_id": str(hop.get("op_id") or ""), "caller": str(hop.get("caller") or ""),
          "notify": str(hop.get("notify") or args.get("notify") or ""),
          "ws": str(hop.get("ws") or args.get("ws") or ""), "args": args,
          "force": str(args.get("force") or "") in ("1", "true", "True"),
          "attempt": 0, "parked": False}
    st["addr"] = parse_addr(d.get("file")) if d.get("file") else {}
    if st["addr"].get("anchor"):
        st["addr"] = {"error": "anchor_unsupported"}
    if st["addr"].get("at") == "ws" and not st["ws"]:
        st["ws"] = st["addr"]["ref"]
    if st["notify"] in ("1", "true", "True"):
        st["notify"] = "1"
    return st


def start_create(st):
    args = st["args"]
    path = path_norm(args.get("path") or d.get("path"))
    if not path:
        finish(st, [fail(st, "bad_path", "a path is /-rooted, without .. or empty segments")])
    data = data_of(args)
    if data is None:
        finish(st, [fail(st, "bad_request", "create needs text or b64")])
    if len(data) > knob("max_bytes", 26214400):
        finish(st, [fail(st, "too_large", "%d bytes > max_bytes" % len(data))])
    st["path"] = path
    st["file"] = "fh-" + secrets.token_hex(6)
    st["new"] = base64.b64encode(data).decode("ascii")
    st["kind"] = "text" if is_text(data) else "binary"
    st["mime"] = str(args.get("mime") or "") or mimetypes.guess_type(path)[0] \
        or ("text/plain" if st["kind"] == "text" else "application/octet-stream")
    ops = [("paths", sel("files", ["file", "tomb"], {"path": path, "tomb": ""}, None, 2)),
           ("idhit", sel("files", ["file"], {"file": st["file"]}))]
    ops += ws_reads(st)
    st["parked"] = True
    emit([store_msg(st, "born0", ops, first=True)])


def ws_reads(st):
    if not st.get("ws"):
        return []
    # `hop.ws` is the workspace NAME (OR-FH-81); every state, the open row
    # first ('open' sorts after 'committed'/'discarded'), so a closed one
    # answers `ws_closed`, not `ws_unknown`
    return [("wsname", sel("ws", ["ws", "name", "root", "base_seq", "state"],
                           {"name": st["ws"]}, [("state", "desc")], 2))]


def ws_row(st, lg):
    """The workspace of the request, or `ws_closed` answered."""
    r = one(lg, "wsname")
    if not r:
        finish(st, [fail(st, "ws_unknown", "no workspace %s" % st["ws"])])
    if r.get("state") != "open":
        finish(st, [fail(st, "ws_closed", "workspace %s is not open" % st["ws"])])
    st["wsid"] = str(r["ws"])
    st["wsrow"] = r


def start_files(st, first=False):
    a = st["addr"]
    if a.get("error"):
        finish(st, [fail(st, a["error"])])
    if not a:
        finish(st, [fail(st, "bad_address", "no file")])
    if a.get("file"):
        ops = [("files", sel("files", ["file", "path", "kind", "mime", "head", "head_seq",
                                        "lock", "tomb", "oneline"], {"file": a["file"]}))]
    else:
        ops = [("files", sel("files", ["file", "path", "kind", "mime", "head", "head_seq",
                                        "lock", "tomb", "oneline"],
                             {"path": a["path"], "tomb": ""}, None, 2))]
    ops += ws_reads(st)
    st["parked"] = True
    emit([store_msg(st, "files", ops, first=first)])


if lane in ("in_write", "in_put"):
    st = fresh_state(lane)
    ops_ok = WRITE_OPS if lane == "in_write" else PUT_OPS
    if st["op"] not in ops_ok:
        emit([fail(st, "unknown_op", "no op %r on %s" % (st["op"], lane))])
    if lane == "in_put" and st["op"] == "create" and not st["ws"]:
        # `in_put create` is a birth in a workspace; without one it would be a
        # main-line birth with `in_derive` (review W m-2)
        emit([fail(st, "bad_request", "in_put create needs ws")])
    if st["op"] == "create":
        start_create(st)
    start_files(st, first=True)

if lane == "checked":
    pid = str(hop.get("op_id") or "")
    if not pid.startswith("w-"):
        note("a hook answer for no request of this cell (%r) -- dropped" % pid)
        emit([])
    # `note` too (OR-FH-66): `too_deep_to_check` passes unchecked, the caller
    # must see it (review W I-1)
    res = {k: d.get(k) for k in ("hook", "lang", "error", "note") if k in d}
    # a request that lost its swing asks the hook again: the older answer goes
    calls = [("clr", dele("pending", {"op_id": pid, "cell": ME + ":hook"})),
             ("hook", ins("pending", {"op_id": pid, "cell": ME + ":hook", "phase": "hook",
                                      "body": json.dumps(res), "at": now()})),
             ("state", sel("pending", ["cell", "body"], {"op_id": pid}, None, 5))]
    emit([{"header": {"route": "write_store", "phase": "hooked", "reply_cell": ME,
                      "cur_call": pid},
           "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                         "text": json.dumps(a)} for cid, a in calls]}])

if lane:
    note("unknown lane %r -- dropped" % lane)
    emit([])

# ================================================================= PHASES
if not hop.get("operation") or str(ctx.get("cur_origin") or "") != ME:
    note("a message with neither a lane nor a store answer -- dropped")
    emit([])
if phase == "done":
    for cid, leg in legs(d).items():
        if leg["error_code"]:
            note("store write %s failed: %s" % (cid, leg["error_code"]))
    emit([])

lg = legs(d)
st, hookres = None, None
for r in rows(lg, "state"):
    try:
        body = json.loads(str(r.get("body") or ""))
    except Exception:
        continue
    if r.get("cell") == ME:
        st = body
    elif r.get("cell") == ME + ":hook":
        hookres = body
if st is None:
    note("phase %r came back without its request (%s) -- dropped" % (
        phase, ",".join("%s=%s" % (k, v["error_code"]) for k, v in lg.items() if v["error_code"])))
    emit([])
bad = [(k, v["error_code"]) for k, v in lg.items() if v["error_code"] and k != "state"]
if bad:
    finish(st, [fail(st, "store_error", ", ".join("%s=%s" % kv for kv in bad))])
stamp = now()
TEXT_OPS = ("replace", "replace_regex", "replace_lines", "insert", "delete", "patch")
FILE_COLS = ["file", "path", "kind", "mime", "head", "head_seq", "lock", "tomb", "oneline"]


def main_line(st):
    return not st.get("ws") and st["lane"] == "in_write"


def b64(data):
    return base64.b64encode(data).decode("ascii")


def restart(st):
    """A lost compare-and-swap: everything from the head on is read again."""
    st["attempt"] = int(st.get("attempt") or 0) + 1
    if st["attempt"] > knob("busy_retries", 3):
        finish(st, [fail(st, "busy", "the head kept moving")])
    for k in ("vrows", "new", "resp", "hook", "cur", "base", "target", "wsf", "row",
              "seq", "hook_note"):
        st.pop(k, None)
    start_files(st)


def goto_blocks(st, need):
    """Fetch the blocks of the versions in `need`, then compute."""
    vr = st.get("vrows") or {}
    hashes = []
    for v in need:
        if v:
            hashes.extend(as_list(vr[v].get("blocks")))
    if not hashes:
        compute_phase(st, {})
    ops = [("blk%d" % i, sel("blocks", ["hash", "enc", "body"],
                             {"file": st["file"], "hash": {"in": tr}}, None, len(tr)))
           for i, tr in enumerate(tranches(hashes))]
    emit([store_msg(st, "blocks", ops)])


def need_versions(st):
    if st["lane"] == "in_put" and st["op"] == "merge3":
        return [st["base"], st["ours"], st["theirs"]]
    return [st.get("base"), st.get("cur"), st.get("target")]


def after_versions(st, lg=None):
    """All version ids known: read the rows not yet in hand, then the blocks."""
    vr = st.setdefault("vrows", {})
    missing = sorted({v for v in need_versions(st) if v and v not in vr})
    if missing:
        emit([store_msg(st, "vers", [("vers", sel(
            "versions", ["version", "blocks", "bytes", "lines", "force"],
            {"file": st["file"], "version": {"in": missing}}, None, len(missing)))])])
    goto_blocks(st, need_versions(st))


def swing(st, setv, cur):
    """The compare-and-swap of the main line: moves only if the head is still
    what was read and no commit holds the file; judged by rows_affected."""
    seq = max(now_us(), int(st["row"].get("head_seq") or 0) + 1)
    st["seq"] = seq
    setv = dict(setv)
    setv["head_seq"] = seq
    emit([store_msg(st, "swung", [("cas", upd("files", setv, {
        "file": st["file"], "head": cur, "lock": "", "tomb": ""}))])])


def ws_swing(st, setv, cur):
    emit([store_msg(st, "swung", [("cas", upd("ws_files", setv, {
        "ws": st["wsid"], "file": st["file"], "working": cur}))])])


def meta(data, kind):
    if kind == "text":
        t = data.decode("utf-8")
        return {"oneline": oneline_of(t), "bytes": len(data), "lines": count_lines(to_lf(t, "\r\n"))}
    return {"oneline": "", "bytes": len(data), "lines": 0}


def version_row(st, ver, data, kind):
    m = meta(data, kind)
    return {"file": st["file"], "version": ver,
            "blocks": json.dumps([block_hash(b) for b in chunk(data, kind == "text")]),
            "bytes": m["bytes"], "lines": m["lines"],
            "parent": st.get("cur") or st.get("base") or "",
            "force": "1" if st.get("force") else "", "made_by": st["op"], "at": stamp}


def base_moved(st, cur_lines, conflicts):
    lines = []
    for c in conflicts:
        for ln in view(cur_lines, c["theirs_from"] - 3, c["theirs_to"] + 3):
            if ln not in lines:
                lines.append(ln)
    finish(st, [fail(st, "base_moved", "the change overlaps what moved since base",
                     current=v12(st["cur"]), lines=lines)])


def compute_phase(st, blocks):
    """The pure core against the fetched content, then the hook."""
    vr = st.get("vrows") or {}

    def content(v):
        if not v:
            return b""
        c = content_of(vr[v], blocks)
        if c is None:
            finish(st, [fail(st, "store_error", "blocks of %s missing" % v12(v))])
        return c

    op, args = st["op"], st["args"]
    if st["lane"] == "in_put" and op == "merge3":
        b, o, t = content(st["base"]), content(st["ours"]), content(st["theirs"])
        if not (is_text(b) and is_text(o) and is_text(t)):
            st["put"] = {"clean": o == t, "conflicts": [] if o == t else [{"from": 0, "to": 0}]}
            st["force"] = o != t
            st["new"] = b64(o)
            st["newkind"] = "binary"
        else:
            eol = eol_of(o.decode("utf-8"))
            m = merge3(to_lf(b.decode("utf-8"), "\r\n"), to_lf(o.decode("utf-8"), "\r\n"),
                       to_lf(t.decode("utf-8"), "\r\n"))
            st["put"] = {"clean": m["clean"],
                         "conflicts": [{"from": c["from"], "to": c["to"]} for c in m["conflicts"]]}
            st["force"] = not m["clean"]
            st["new"] = b64(from_lf(m["text"], eol).encode("utf-8"))
            st["newkind"] = "text"
        st["hook"] = "forced" if st["force"] else "none"
        go_have(st)

    base_b = content(st.get("base"))
    cur_b = content(st.get("cur")) if st.get("cur") != st.get("base") else base_b
    kind = st.get("kind") or "text"
    stage = None
    if op in TEXT_OPS:
        if kind != "text" or not is_text(base_b):
            finish(st, [fail(st, "not_text", "%s works on text files" % op)])
        base_t = base_b.decode("utf-8")
        eol = eol_of(base_t)
        r = compute(op, args, to_lf(base_t, eol))
        if "error" in r:
            code = r.pop("error")
            finish(st, [fail(st, code, r.pop("message", ""), **r)])
        stage = r.get("stage")
        new_b = from_lf(r["text"], eol).encode("utf-8")
    elif op in ("overwrite", "create"):
        new_b = data_of(args)
        if new_b is None:
            finish(st, [fail(st, "bad_request", "%s needs text or b64" % op)])
    elif op == "revert":
        new_b = content(st["target"])
    else:
        finish(st, [fail(st, "unknown_op")])

    rebased = False
    if st.get("cur") != st.get("base"):
        if not (is_text(base_b) and is_text(cur_b) and is_text(new_b)):
            finish(st, [fail(st, "base_moved", "a binary file moved since base",
                             current=v12(st["cur"]), lines=[])])
        eol = eol_of(cur_b.decode("utf-8"))
        cur_lf = to_lf(cur_b.decode("utf-8"), "\r\n")
        m = merge3(to_lf(base_b.decode("utf-8"), "\r\n"), to_lf(new_b.decode("utf-8"), "\r\n"),
                   cur_lf)
        if not m["clean"]:
            base_moved(st, split_lines(cur_lf)[0], m["conflicts"])
        new_b = from_lf(m["text"], eol).encode("utf-8")
        rebased = True
    if len(new_b) > knob("max_bytes", 26214400):
        finish(st, [fail(st, "too_large", "%d bytes > max_bytes" % len(new_b))])
    newkind = "text" if is_text(new_b) else "binary"
    resp = {"file": st["file"], "base": v12(st.get("base"))}
    if stage:
        resp["stage"] = stage
    if rebased:
        resp["rebased"] = True
    if newkind == "text" and is_text(base_b):
        a_lf = to_lf(base_b.decode("utf-8"), "\r\n")
        b_lf = to_lf(new_b.decode("utf-8"), "\r\n")
        dl = unified(a_lf, b_lf).split("\n") if a_lf != b_lf else []
        cap = knob("diff_lines", 400)
        if len(dl) > cap:
            dl, resp["truncated"] = dl[:cap], True
        resp["diff"] = "\n".join(dl)
        if op == "overwrite" and 0 < changed_share(a_lf, b_lf) <= knob("overwrite_hint", 0.05):
            resp["hint"] = "use_replace"
    else:
        resp["diff"] = ""
    st["resp"] = resp
    st["newkind"] = newkind
    st["new"] = b64(new_b)
    st["orig"] = b64(base_b) if newkind == "text" and is_text(base_b) else ""
    new_v = version_of(new_b)
    if st["lane"] == "in_write" and new_v == st.get("cur"):
        resp.update({"version": v12(new_v), "hook": "none"})
        finish(st, [reply(st, resp)])
    if st["lane"] == "in_put" and new_v == st.get("base"):
        finish(st, [reply(st, {"version": new_v})])
    go_hook(st)


def go_hook(st):
    """Ask `./guard` before anything lands -- unless `force` (which skips the
    hook and nothing else) or the content is not text. The request is parked
    first, so the hook's answer finds it."""
    if st.get("force"):
        st["hook"] = "forced"
        go_have(st)
    if st.get("newkind") != "text":
        st["hook"] = "none"
        go_have(st)
    emit([store_msg(st, "guard", [])])


def go_have(st):
    """Which of the new blocks and whether the new version exist already
    (per file: a block of another file is never borrowed, R-FH-1 Auflage 2)."""
    data = base64.b64decode(st["new"])
    blocks = chunk(data, st["newkind"] == "text")
    st["newv"] = version_of(data)
    ops = [("hv%d" % i, sel("blocks", ["hash"], {"file": st["file"], "hash": {"in": tr}},
                            None, len(tr)))
           for i, tr in enumerate(tranches([block_hash(b) for b in blocks]))]
    ops.append(("vex", sel("versions", ["version"], {"file": st["file"], "version": st["newv"]})))
    emit([store_msg(st, "have", ops)])


def syntax_error(st, res):
    err = res.get("error") or {}
    line = int(err.get("line") or 0)
    new_l = split_lines(to_lf(base64.b64decode(st["new"]).decode("utf-8"), "\r\n"))[0]
    orig_l = split_lines(to_lf(base64.b64decode(st.get("orig") or "").decode("utf-8"), "\r\n"))[0]
    if line <= 0 or line > len(new_l):
        line = len(new_l) if line > len(new_l) else 1
    finish(st, [fail(st, "syntax", str(err.get("message") or "the hook rejected the content"),
                     lang=str(res.get("lang") or ""), line=int(err.get("line") or 0),
                     col=int(err.get("col") or 0), preview=view(new_l, line - 5, line + 5),
                     original=view(orig_l, line - 5, line + 5))])


def answer_write(st, extra_msgs=()):
    resp = dict(st["resp"])
    resp["version"] = v12(st["newv"])
    resp["hook"] = st.get("hook") or "none"
    if st.get("hook_note"):
        resp["hook_note"] = st["hook_note"]
    if st.get("ws"):
        resp["ws"] = st["ws"]
    finish(st, [reply(st, resp)] + list(extra_msgs))


def derive_msg(st, version):
    """`in_derive` once per swing of the main line, with the request's
    `notify` and `caller` (README § 2.9 docking point of B2)."""
    return {"header": {"route": "in_derive", "notify": st.get("notify") or "",
                       "caller": st.get("caller") or "", "op_id": st.get("op_id") or ""},
            "file": st["file"], "version": version}


# ---- dispatch of the store answers ---------------------------------------------
if phase == "born0":
    if st.get("ws"):
        ws_row(st, lg)
    if one(lg, "idhit"):
        st["file"] = "fh-" + secrets.token_hex(6)
        ops = [("paths", sel("files", ["file", "tomb"], {"path": st["path"], "tomb": ""},
                             None, 2)),
               ("idhit", sel("files", ["file"], {"file": st["file"]}))] + ws_reads(st)
        emit([store_msg(st, "born0", ops)])
    taken = [r for r in rows(lg, "paths") if not r.get("tomb")]
    if taken:
        finish(st, [fail(st, "path_taken", "%s is taken" % st["path"], file=taken[0]["file"])])
    data = base64.b64decode(st["new"])
    st["newkind"] = st["kind"]
    st["resp"] = {"file": st["file"], "base": "", "diff": ""}
    st["orig"] = ""
    go_hook(st)

if phase == "files":
    row = None
    for r in rows(lg, "files"):
        row = row or r
    if st.get("ws"):
        ws_row(st, lg)
    if not row:
        finish(st, [fail(st, "not_found", "no file %s" % (st["addr"].get("file")
                                                          or st["addr"].get("path")))])
    if row.get("tomb"):
        finish(st, [fail(st, "tombstoned", "file %s was removed" % row["file"], file=row["file"])])
    st["row"], st["file"], st["kind"] = row, row["file"], row.get("kind") or "text"
    args, op, F = st["args"], st["op"], row["file"]
    ops = []
    if st["lane"] == "in_put":
        names = ("base", "ours", "theirs") if op == "merge3" else ("base",)
        for n in names:
            pfx = str(args.get(n) or "").lower()
            if not HEX_RE.match(pfx):
                finish(st, [fail(st, "bad_request", "%s needs a version %s" % (op, n))])
            ops.append((n, vsel(F, pfx)))
        emit([store_msg(st, "ctx", ops)])
    if op == "snapshot":
        name = str(args.get("name") or "")
        if not name:
            finish(st, [fail(st, "bad_request", "snapshot needs a name")])
        ops.append(("snap", sel("snaps", ["name"], {"file": F, "name": name})))
        at = st["addr"].get("at")
        if at == "v":
            ops.append(("target", vsel(F, st["addr"]["ref"])))
        elif at == "snap":
            ops.append(("tsnap", sel("snaps", ["version"], {"file": F, "name": st["addr"]["ref"]})))
        emit([store_msg(st, "ctx", ops)])
    base = str(args.get("base") or d.get("base") or "").lower()
    if base and not HEX_RE.match(base):
        finish(st, [fail(st, "bad_request", "base is a version")])
    if main_line(st):
        if not base:
            finish(st, [fail(st, "base_required", "every write carries its base")])
        if not row.get("head"):
            finish(st, [fail(st, "not_found", "file %s lives only in a workspace" % F)])
        if row.get("lock"):
            ops.append(("lockc", sel("commits", ["commit", "state", "deadline"],
                                     {"commit": row["lock"]})))
        ops.append(("cur", sel("versions", ["version", "blocks", "bytes", "lines", "force"],
                               {"file": F, "version": row["head"]})))
    else:
        ops.append(("wsf", sel("ws_files", ["base", "working", "state"],
                               {"ws": st["wsid"], "file": F})))
        ops.append(("atseq", sel("line", ["version", "seq"],
                                 {"file": F, "seq": {"lte": int(st["wsrow"].get("base_seq") or 0)}},
                                 [("seq", "desc")], 1)))
    if base:
        ops.append(("base", vsel(F, base)))
    st["basepfx"] = base
    if op == "revert":
        tv = str(args.get("version") or "").lower()
        if not HEX_RE.match(tv):
            finish(st, [fail(st, "bad_request", "revert needs a version")])
        ops.append(("target", vsel(F, tv)))
        st["targetpfx"] = tv
    emit([store_msg(st, "ctx", ops)])

if phase == "ctx":
    F, op, args, row = st["file"], st["op"], st["args"], st["row"]
    for cid in ("cur", "base", "target"):
        for r in rows(lg, cid):
            st.setdefault("vrows", {})[r["version"]] = r
    if st["lane"] == "in_put":
        for n in (("base", "ours", "theirs") if op == "merge3" else ("base",)):
            st[n] = resolve(st, lg, n, str(args.get(n)).lower())
        st["cur"] = st["base"]
        after_versions(st)
    if op == "snapshot":
        if one(lg, "snap"):
            finish(st, [fail(st, "snap_exists", "snapshot %s exists" % args.get("name"))])
        at = st["addr"].get("at")
        if at == "v":
            ver = resolve(st, lg, "target", st["addr"]["ref"])
        elif at == "snap":
            r = one(lg, "tsnap")
            if not r:
                finish(st, [fail(st, "snap_unknown", "no snapshot %s" % st["addr"]["ref"])])
            ver = r["version"]
        else:
            ver = row.get("head") or ""
            if not ver:
                finish(st, [fail(st, "not_found", "file %s lives only in a workspace" % F)])
        st["newv"] = ver
        emit([store_msg(st, "snapped", [("snapins", ins("snaps", {
            "file": F, "name": str(args.get("name")), "version": ver, "at": stamp}))])])
    if main_line(st):
        lk = one(lg, "lockc")
        if row.get("lock"):
            msgs = []
            if lk and (lk.get("state") == "committed"
                       or (lk.get("state") == "prepared" and later(stamp, lk.get("deadline")))):
                msgs.append({"header": {"route": "in_recover"}, "commit": row["lock"]})
            finish(st, [fail(st, "busy", "a commit holds %s" % F)] + msgs)
        st["cur"] = row["head"]
    else:
        wsf = one(lg, "wsf")
        if wsf:
            if wsf.get("state") == "removed":
                finish(st, [fail(st, "not_found", "file %s is removed in %s" % (F, st["ws"]))])
            st["wsf"] = wsf
            st["cur"] = wsf.get("working") or ""
        else:
            # the main line at the workspace's base_seq: the head when it moved
            # last before it (V's `ws_tree` rule, review W m-6 -- also right
            # when a crash left a swing without its `line` row), else the last
            # `line` row up to it
            bseq = int(st["wsrow"].get("base_seq") or 0)
            at = one(lg, "atseq")
            if row.get("head") and int(row.get("head_seq") or 0) <= bseq:
                st["cur"] = row["head"]
            elif at and at.get("version"):
                st["cur"] = at["version"]
            else:
                finish(st, [fail(st, "not_found", "file %s is not in workspace %s" % (F, st["ws"]))])
    st["base"] = resolve(st, lg, "base", st["basepfx"], [st["cur"]]) if st["basepfx"] \
        else st["cur"]
    if op == "revert":
        st["target"] = resolve(st, lg, "target", st["targetpfx"], [st["cur"], st["base"]])
    if op == "remove":
        if st["base"] != st["cur"]:
            finish(st, [fail(st, "base_moved", "the file moved since base",
                             current=v12(st["cur"]), lines=[])])
        st["newv"] = st["cur"]
        st["resp"] = {"file": F, "base": v12(st["base"]), "diff": ""}
        st["hook"] = "none"
        if main_line(st):
            swing(st, {"tomb": stamp}, st["cur"])
        if st.get("wsf"):
            ws_swing(st, {"state": "removed", "at": stamp}, st["cur"])
        emit([store_msg(st, "wsdone", [("wsins", ins("ws_files", {
            "ws": st["wsid"], "file": F, "base": st["cur"], "working": st["cur"],
            "state": "removed", "at": stamp}))])])
    after_versions(st)

if phase == "vers":
    for r in rows(lg, "vers"):
        st.setdefault("vrows", {})[r["version"]] = r
    for v in need_versions(st):
        if v and v not in st["vrows"]:
            finish(st, [fail(st, "store_error", "version %s has no row" % v12(v))])
    goto_blocks(st, need_versions(st))

if phase == "blocks":
    compute_phase(st, block_rows(lg))

if phase == "guard":
    text = base64.b64decode(st["new"]).decode("utf-8")
    emit([{"header": {"route": "in_check", "op_id": st["pid"]},
           "path": (st.get("row") or {}).get("path") or st.get("path") or "",
           "mime": (st.get("row") or {}).get("mime") or st.get("mime") or "",
           "kind": "text", "text": text}])

if phase == "hooked":
    res = hookres or {}
    if res.get("hook") == "failed":
        syntax_error(st, res)
    st["hook"] = "ok" if res.get("hook") == "ok" else "none"
    if res.get("note"):
        st["hook_note"] = str(res["note"])
    go_have(st)

if phase == "have":
    have = set()
    for cid in lg:
        if cid.startswith("hv"):
            have |= {str(r.get("hash")) for r in rows(lg, cid)}
    data = base64.b64decode(st["new"])
    text = st["newkind"] == "text"
    ops, seen = [], set()
    for i, b in enumerate(chunk(data, text)):
        h = block_hash(b)
        if h in have or h in seen:
            continue
        seen.add(h)
        ops.append(("b%d" % i, ins("blocks", {
            "file": st["file"], "hash": h, "enc": "utf8" if text else "b64", "size": len(b),
            "body": b.decode("utf-8") if text else b64(b), "first_seen": stamp})))
    if not one(lg, "vex"):
        ops.append(("ver", ins("versions", version_row(st, st["newv"], data, st["newkind"]))))
        for k, part in enumerate(st["args"].get("derived") or []):
            if isinstance(part, dict) and st["op"] in ("create", "overwrite"):
                ops.append(("drv%d" % k, ins("derived", {
                    "file": st["file"], "version": st["newv"], "kind": "text",
                    "part": int(part.get("part") or k + 1), "body": str(part.get("text") or "")})))
    if st.get("ws") and st["op"] != "create" and st["lane"] == "in_write" and not st.get("wsf"):
        ops.append(("wsins", ins("ws_files", {"ws": st["wsid"], "file": st["file"],
                                              "base": st["cur"], "working": st["cur"],
                                              "state": "touched", "at": stamp})))
    emit([store_msg(st, "stored", ops)])

if phase == "stored":
    data = base64.b64decode(st["new"])
    if st["op"] == "create":
        F, m = st["file"], meta(data, st["newkind"])
        ops = []
        if st.get("ws"):
            ops.append(("born", ins("files", {
                "file": F, "path": st["path"], "kind": st["newkind"], "mime": st["mime"],
                "head": "", "head_seq": 0, "lock": "", "tomb": "", "oneline": m["oneline"],
                "bytes": m["bytes"], "lines": m["lines"], "born_at": stamp})))
            ops.append(("wsins", ins("ws_files", {"ws": st["wsid"], "file": F, "base": "",
                                                  "working": st["newv"], "state": "created",
                                                  "at": stamp})))
        else:
            seq = now_us()
            ops.append(("born", ins("files", {
                "file": F, "path": st["path"], "kind": st["newkind"], "mime": st["mime"],
                "head": st["newv"], "head_seq": seq, "lock": "", "tomb": "",
                "oneline": m["oneline"], "bytes": m["bytes"], "lines": m["lines"],
                "born_at": stamp})))
            ops.append(("line", ins("line", {"file": F, "seq": seq, "version": st["newv"],
                                             "prev": "", "op": "create", "note": "", "ws": "",
                                             "commit": "", "at": stamp})))
        emit([store_msg(st, "born", ops)])
    if st["lane"] == "in_put":
        out = {"version": st["newv"]}
        if st["op"] == "merge3":
            out.update(st["put"])
        finish(st, [reply(st, out)])
    m = meta(data, st["newkind"])
    if main_line(st):
        # the first line stands in for a summary only until ./derive has one:
        # a swing keeps what is there (OR-FH-72), `create` sets it
        m.pop("oneline", None)
        m.update({"head": st["newv"], "kind": st["newkind"]})
        swing(st, m, st["cur"])
    old = (st.get("wsf") or {}).get("state") or "touched"
    state = "created" if old == "created" else (
        "conflict" if old == "conflict" and st["newkind"] == "text"
        and has_marks(data.decode("utf-8")) else "touched")
    ws_swing(st, {"working": st["newv"], "state": state, "at": stamp}, st["cur"])

if phase == "swung":
    if lg.get("cas", {}).get("rows_affected", 0) != 1:
        restart(st)
    if not main_line(st):
        answer_write(st)
    note_ = v12(st["target"]) if st["op"] == "revert" else ""
    emit([store_msg(st, "lined", [("line", ins("line", {
        "file": st["file"], "seq": st["seq"], "version": st["newv"], "prev": st["cur"],
        "op": st["op"], "note": note_, "ws": "", "commit": "", "at": stamp}))])])

if phase == "lined":
    if st["op"] == "remove":
        answer_write(st)
    answer_write(st, [derive_msg(st, st["newv"])])

if phase == "born":
    if st.get("ws"):
        if st["lane"] == "in_put":
            finish(st, [reply(st, {"file": st["file"], "version": st["newv"]})])
        answer_write(st)
    answer_write(st, [derive_msg(st, st["newv"])])

if phase in ("snapped", "wsdone"):
    if phase == "snapped":
        finish(st, [reply(st, {"file": st["file"], "version": v12(st["newv"])})])
    answer_write(st)

note("store answer in unknown phase %r -- dropped" % phase)
finish(st, [])
